DO $$
DECLARE
  m_119_s_331 integer;
  m_119_h_r_1 integer;
  m_119_h_r_4 integer;
  m_119_h_r_3486 integer;
  rc integer;
BEGIN

  -- ── measures ──────────────────────────────────────────────────────────────
  -- Every lookup keys on measure_type, congress, chamber AND number: the record also
  -- holds a 117th-Congress H.R. 1 (For the People Act) and H.R. 4 (John R. Lewis Voting
  -- Rights Advancement Act), and a lookup on number alone would attribute reconciliation
  -- and rescission votes to voting-rights bills.

  -- S. 331 (119th senate)
  --   Created by migration 20260721170000_seed_legislation_expansion.sql, inside an IF
  --   m_id IS NULL guard. Already status 'enacted'; P.L. 119-26, signed 2025-07-16.
  SELECT id INTO m_119_s_331 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119
     AND chamber = 'senate' AND number = 'S. 331' LIMIT 1;
  IF m_119_s_331 IS NULL THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: S. 331 (119th senate) is not in vr_measures — it is expected to exist and is never created here.';
  END IF;

  -- H.R. 1 (119th house)
  --   Created by migration 20260724120000_seed_senate_voting_record.sql. Status is already
  --   'enacted' and external_ids already carries P.L. 119-21 (migration 20260807000000),
  --   so there is nothing to backfill and nothing is rewritten.
  SELECT id INTO m_119_h_r_1 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119
     AND chamber = 'house' AND number = 'H.R. 1' LIMIT 1;
  IF m_119_h_r_1 IS NULL THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: H.R. 1 (119th house) is not in vr_measures — it is expected to exist and is never created here.';
  END IF;

  -- H.R. 4 (119th house)
  --   Created by migration 20260719150000_seed_rescissions_voting_record.sql. Already
  --   status 'enacted'; P.L. 119-28, signed 2025-07-24. Not rewritten.
  SELECT id INTO m_119_h_r_4 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119
     AND chamber = 'house' AND number = 'H.R. 4' LIMIT 1;
  IF m_119_h_r_4 IS NULL THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: H.R. 4 (119th house) is not in vr_measures — it is expected to exist and is never created here.';
  END IF;

  -- H.R. 3486 (119th house) — To amend the Immigration and Nationality Act to increase penalties for individuals who illegally enter and reenter the United States after being removed, and for other purposes.
  --   Summary written from the engrossed text
  --   https://www.govinfo.gov/content/pkg/BILLS-119hr3486eh/xml/BILLS-119hr3486eh.xml, not
  --   from a secondary description. vr_measures has no text_url column, so the citation
  --   lives here.
  SELECT id INTO m_119_h_r_3486 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119
     AND chamber = 'house' AND number = 'H.R. 3486' LIMIT 1;
  IF m_119_h_r_3486 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('bill', 119, 'house', 'H.R. 3486', 'To amend the Immigration and Nationality Act to increase penalties for individuals who illegally enter and reenter the United States after being removed, and for other purposes.', 'Stop Illegal Entry Act of 2025',
      'A two-section sentencing bill amending the criminal provisions of the Immigration and Nationality Act. Section 2 raises the maximum term for improper entry under INA section 275 (8 U.S.C. 1325) from 2 years to 5 years, and adds a new subsection (e) imposing a mandatory minimum of 5 years — with a maximum of any term of years or life — on a person who entered unlawfully, eluded inspection or entered by willful misrepresentation and is thereafter convicted of any crime punishable by more than 1 year of imprisonment. Section 3 rewrites the reentry penalties of INA section 276 (8 U.S.C. 1326): a 10-year maximum in general; 15 years for a person removed after 3 or more misdemeanours involving drugs or crimes against the person; 10 years, not to run concurrently, for reentry after removal on terrorism grounds; 10 years for a person removed 3 or more times; and a mandatory minimum of 10 years for reentry after conviction of an aggravated felony, any felony, or any crime punishable by more than 1 year. It also transfers the section''s consent authority from the Attorney General to the Secretary of Homeland Security. Sponsored by Rep. Stephanie Bice (R-OK-5) with 5 cosponsors, reported amended by the Judiciary Committee as H. Rept. 119-200, and passed the House 226-197 on 2025-09-11 (roll 119/1/264) under the rule provided by H. Res. 682. Received in the Senate 2025-09-15, where it has had no further action: this is a House-passed bill, NOT law. Summary written from the engrossed text (BILLS-119hr3486eh), not from a secondary description.',
      DATE '2025-05-19', 'passed_house', 'https://www.congress.gov/bill/119th-congress/house-bill/3486', 'Congress.gov', '{"congressGovId":"hr3486-119"}'::jsonb)
    RETURNING id INTO m_119_h_r_3486;
  END IF;

