  -- ── sponsorship (vr_positions) ─────────────────────────────────────────────
  -- A 226-197 roll call records how members voted; putting your name on the bill at
  -- introduction, four months before the floor, records something the roll cannot. H.R.
  -- 3486 had one sponsor and five cosponsors, and db/vr-member-map.json resolves exactly
  -- one of the six. The sponsor, Rep. Stephanie Bice (R-OK-5), is NOT on the roster, so
  -- sponsor_id on the measure row is left NULL and her sponsorship is recorded in the
  -- summary text rather than as a row that points at no profile.
  IF m_119_h_r_3486 IS NOT NULL THEN
    INSERT INTO vr_positions (measure_id, politician_id, action_type, supports, acted_at, source_url, note) VALUES
      (m_119_h_r_3486, 'luna', 'cosponsor', true, TIMESTAMPTZ '2025-05-19T00:00:00Z',
       'https://www.congress.gov/bill/119th-congress/house-bill/3486', 'Original cosponsor on introduction, 2025-05-19, alongside Reps. Knott, Zinke, Schmidt and Gill. Sponsor Rep. Stephanie Bice (R-OK-5) is not on the PolitiDex roster, so her sponsorship is recorded here in prose and not as a row — a position cannot be attributed to a profile that does not exist.')
    ON CONFLICT (measure_id, politician_id, action_type) DO NOTHING;
  END IF;

  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the rationale and a primary source on every
  -- row — scripts/test-mapping-discipline.mjs requires both. ON CONFLICT (measure_id,
  -- issue_key) DO NOTHING, so a re-emission of a live row is a no-op and cannot rewrite
  -- a rationale another migration authored.

  -- S. 331 (119th) — immig_fentanyl yea_supports w100, tough_on_crime yea_supports w75, health_mental yea_opposes w45
  --   All three byte-identical to 20260721170000 — immig_fentanyl primary, tough_on_crime,
  --   and health_mental as yea_opposes for the treatment-over-enforcement objection. No
  --   new key: healthcare was considered and declined because health_mental already
  --   carries that reading more precisely.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_331, 'immig_fentanyl', 100, true, 'yea_supports',
      'Directly targets the fentanyl overdose crisis by making class-wide Schedule I placement of fentanyl-related substances permanent.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/331'),
    (m_119_s_331, 'tough_on_crime', 75, false, 'yea_supports',
      'Attaches mandatory-minimum penalties and quantity triggers to fentanyl-analogue offenses.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/331'),
    (m_119_s_331, 'health_mental', 45, false, 'yea_opposes',
      'Recorded neutrally: some public-health advocates argue permanent scheduling and mandatory minimums emphasize enforcement over treatment — a Yea is tagged as cutting against that concern.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/331')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 1 (119th) — lower_taxes yea_supports w100, cut_spending yea_supports w70, healthcare yea_opposes w60, border_security yea_supports w55, lands_energy yea_supports w40
  --   Five of H.R. 1's FOURTEEN live mappings, byte-identical to what migration
  --   20260724120000 wrote. The other nine (tax_middle_class, national_debt,
  --   family_support, climate_action, energy_production, deportations, strong_defense,
  --   school_choice, edu_college_cost) were first written by
  --   20260720000000_hr1_omnibus_component_issues.sql and are NOT re-emitted, because
  --   db/vr-issue-seed.json does not mirror them and applyCuratedIssueSeed() upserts —
  --   mirroring the wrong one of two candidate texts would overwrite nine good rationales
  --   for no gain. All fourteen score the 180 member votes this pass attributes; the five
  --   below are simply the ones the curated seed can assert.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_1, 'lower_taxes', 100, true, 'yea_supports',
      'Extends and expands the 2017 individual and business tax cuts.',
      'https://www.congress.gov/bill/119th-congress/house-bill/1'),
    (m_119_h_r_1, 'cut_spending', 70, false, 'yea_supports',
      'Enacts net spending reductions through budget reconciliation.',
      'https://www.congress.gov/bill/119th-congress/house-bill/1'),
    (m_119_h_r_1, 'healthcare', 60, false, 'yea_opposes',
      'Reduces federal Medicaid spending and tightens eligibility; a yea vote cuts against expanding healthcare access.',
      'https://www.congress.gov/bill/119th-congress/house-bill/1'),
    (m_119_h_r_1, 'border_security', 55, false, 'yea_supports',
      'Provides new funding for border enforcement and immigration operations.',
      'https://www.congress.gov/bill/119th-congress/house-bill/1'),
    (m_119_h_r_1, 'lands_energy', 40, false, 'yea_supports',
      'Expands onshore and offshore oil, gas, and coal leasing on federal land.',
      'https://www.congress.gov/bill/119th-congress/house-bill/1')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 4 (119th) — cut_spending yea_supports w100, gov_waste yea_supports w70, national_debt yea_supports w40, america_first_fp yea_supports w65
  --   cut_spending, gov_waste and national_debt are byte-identical to 20260719150000 and
  --   are no-ops; they are here because the curated seed carries them and the ingest
  --   endpoint re-asserts the seed. FOUR further mappings are live on this measure and are
  --   NOT emitted here — america_first 60, audit_spending 55, gov_services 45 yea_opposes
  --   and free_speech 30 yea_opposes, all from
  --   20260721140000_seed_legislation_deepdive.sql — so H.R. 4 already carries seven axes
  --   and leaves this pass with eight. america_first_fp is the ONE new one. It sits
  --   deliberately beside the already-live america_first: same $7.9 billion of rescinded
  --   State and USAID balances, but america_first_fp is the chip whose own text says
  --   'rethink foreign aid commitments' and the chip 22 rostered members hold a position
  --   on, against 4 for america_first. Both are yea_supports and cannot contradict; the
  --   opposite-direction precedent is H.R. 815, mapped america_first_fp 70 yea_OPPOSES by
  --   20260810000000. See the header for why foreign_balance and checks_balances were
  --   declined, and why gov_services is recorded as a disagreement rather than removed.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_4, 'cut_spending', 100, true, 'yea_supports',
      'Rescinds previously appropriated funds, cutting federal spending.',
      'https://www.congress.gov/bill/119th-congress/house-bill/4'),
    (m_119_h_r_4, 'gov_waste', 70, false, 'yea_supports',
      'Framed by supporters as clawing back wasteful or low-priority spending.',
      'https://www.congress.gov/bill/119th-congress/house-bill/4'),
    (m_119_h_r_4, 'national_debt', 40, false, 'yea_supports',
      'Modestly reduces outlays against the federal deficit.',
      'https://www.congress.gov/bill/119th-congress/house-bill/4'),
    (m_119_h_r_4, 'america_first_fp', 65, false, 'yea_supports',
      'Nineteen of the enrolled Act''s twenty rescission paragraphs strike unobligated foreign-assistance balances, roughly $7.9 billion in all: Development Assistance $2.5B, Economic Support Fund $1.65B, Migration and Refugee Assistance $800M, International Disaster Assistance $496M, Assistance for Europe, Eurasia and Central Asia $460M, International Organizations and Programs $436.9M, Global Health Programs $500M, the Clean Technology Fund $125M, USAID Operating Expenses $125M and the United States Institute of Peace $15M, among others. The america_first_fp chip reads "Put U.S. interests first, end endless wars and rethink foreign aid commitments" — rescinding appropriated foreign aid is that chip''s own stated content, so a yea supports it. Weighted 65 and not primary because the measure''s controlling axis is still spending, not foreign policy.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr4enr/xml/BILLS-119hr4enr.xml')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 3486 (119th) — tough_on_crime yea_supports w100, border_security yea_supports w65
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_3486, 'tough_on_crime', 100, true, 'yea_supports',
      'The bill''s entire substance is sentence length. Section 2 raises the improper-entry maximum under 8 U.S.C. 1325 from 2 to 5 years and adds a 5-year mandatory minimum, up to life, for a person who entered unlawfully and is later convicted of any crime punishable by more than a year. Section 3 rewrites the reentry penalties of 8 U.S.C. 1326 with a 10-year general maximum, 15 years after three or more drug or person-crime misdemeanours, a non-concurrent 10 years after removal on terrorism grounds, and a 10-year mandatory minimum after an aggravated-felony or any-felony conviction. The tough_on_crime chip reads "crack down on crime with strong policing and tougher sentences for offenders"; a yea is a vote for tougher sentences, which is the chip''s own text.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr3486eh/xml/BILLS-119hr3486eh.xml'),
    (m_119_h_r_3486, 'border_security', 65, false, 'yea_supports',
      'Illegal entry and reentry are the two federal offences the immigration-enforcement system rests on, and this bill raises the penalty for both — the axis the border_security chip labels ''Strong Border & Enforcement''. Coded secondary at 65 rather than primary because the bill adds no barrier, no agent, no detention bed and no removal authority: it is enforcement severity, not enforcement capacity. The related deportations key is declined outright for the same reason.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr3486eh/xml/BILLS-119hr3486eh.xml')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in every spending and immigration mapping earlier passes wrote and stop meaning
-- anything.
--
-- Counts assert >= rather than =, and for two independent reasons. Mappings: eleven of
-- the fourteen rows emitted above already existed byte-identically, and the four
-- measures carry thirteen further live mappings this pass deliberately does not mirror —
-- nine on H.R. 1 and four on H.R. 4 — while ON CONFLICT DO NOTHING makes every
-- re-emission a no-op, so the true count on these measures is far higher than the file
-- writes. Member votes: 5 of the 8 rolls were already live and hold votes an earlier
-- attribution path wrote, some of them for members this roster does not carry.
--
-- The orphan check is scoped to the 3 rolls this pass CREATED (house 119/1/145, 166 and
-- 264). The five that were already live are excluded: their pre-existing member votes
-- came through an earlier and wider path, and failing on those would be failing on
-- somebody else's data.
--
-- Two assertions are specific rather than aggregate, because they are the two things
-- this pass exists to do. The top-up check names each already-live roll and its new
-- floor, so a roll that silently failed to gain voters is caught rather than averaged
-- away. The america_first_fp check confirms the pass's ONE new mapping actually landed
-- on the 119th Congress H.R. 4 and not on the 117th Congress voting-rights bill of the
-- same number.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_pos integer;
  n_afp integer;
  n_hr1_axes integer;
  n_hr4_axes integer;
  n_senate127 integer;
  n_house168 integer;
  n_senate372 integer;
  n_house190 integer;
  n_senate411 integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 1::integer, 127::integer),
    ('house'::text, 119::integer, 1::integer, 145::integer),
    ('house'::text, 119::integer, 1::integer, 166::integer),
    ('house'::text, 119::integer, 1::integer, 168::integer),
    ('senate'::text, 119::integer, 1::integer, 372::integer),
    ('house'::text, 119::integer, 1::integer, 190::integer),
    ('senate'::text, 119::integer, 1::integer, 411::integer),
    ('house'::text, 119::integer, 1::integer, 264::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), fresh (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 119::integer, 1::integer, 145::integer),
    ('house'::text, 119::integer, 1::integer, 166::integer),
    ('house'::text, 119::integer, 1::integer, 264::integer)
  ), fresh_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN fresh f
      ON r.chamber = f.chamber AND r.congress = f.congress
     AND r.session = f.session AND r.roll_number = f.roll_number
  ), mine (measure_type, congress, chamber, number) AS (VALUES
    ('bill'::text, 119::integer, 'senate'::text, 'S. 331'::text),
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 1'::text),
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 4'::text),
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 3486'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.measure_type = k.measure_type AND m.congress = k.congress
     AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM fresh_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'andy_kim', 'aoc', 'barrasso', 'bennie_thompson', 'bmoore', 'boebert', 'booker', 'brian_mast', 'britt', 'bruce_westerman', 'chris_murphy', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'dan_goldman', 'don_bacon', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'graham', 'grassley', 'greg_landsman', 'haley_stevens', 'hawley', 'jake_auchincloss', 'jason_smith', 'jayapal', 'jeffries', 'jim_jordan', 'jim_mcgovern', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'khanna', 'lankford', 'lee', 'mariannette_miller_meeks', 'mark_kelly', 'massie', 'maxine_waters', 'mcconnell', 'meeks', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_simpson', 'mike_waltz', 'mtg', 'murkowski', 'omar', 'owens', 'rand_paul', 'reed', 'rick_crawford', 'risch', 'rob_bresnahan', 'robert_garcia', 'rosen', 'rubio', 'ryan_mackenzie', 'sanders', 'scalise', 'schiff', 'schumer', 'scott_perry', 'seth_moulton', 'shaheen', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'tgabbard', 'thune', 'tim_scott', 'tlaib', 'tom_cole', 'tom_suozzi', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'warnock', 'warren', 'zeldin'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('america_first_fp', 'border_security', 'cut_spending', 'gov_waste', 'health_mental', 'healthcare', 'immig_fentanyl', 'lands_energy', 'lower_taxes', 'national_debt', 'tough_on_crime')),
         (SELECT count(*) FROM vr_positions p
           WHERE p.measure_id IN (SELECT id FROM measure_ids) AND p.action_type IN ('sponsor', 'cosponsor')),
         (SELECT count(*) FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
           WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house'
             AND m.number = 'H.R. 4' AND i.issue_key = 'america_first_fp'),
         (SELECT count(*) FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
           WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house'
             AND m.number = 'H.R. 1'),
         (SELECT count(*) FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
           WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house'
             AND m.number = 'H.R. 4')
    INTO n_rolls, n_votes, n_orphan, n_issues, n_pos, n_afp, n_hr1_axes, n_hr4_axes;

  SELECT count(*) INTO n_senate127 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'senate' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 127;
  SELECT count(*) INTO n_house168 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'house' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 168;
  SELECT count(*) INTO n_senate372 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'senate' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 372;
  SELECT count(*) INTO n_house190 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'house' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 190;
  SELECT count(*) INTO n_senate411 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'senate' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 411;

  RAISE NOTICE 'Fiscal/enforcement pass: % roll calls, % member votes, % issue mappings, % sponsorship rows', n_rolls, n_votes, n_issues, n_pos;
  RAISE NOTICE 'Fiscal/enforcement pass: H.R. 1 (119th) carries % mapped issue axes, H.R. 4 carries %', n_hr1_axes, n_hr4_axes;
  RAISE NOTICE 'Fiscal/enforcement pass: senate 119/1 roll 127 (S. 331) carries % attributed member votes', n_senate127;
  RAISE NOTICE 'Fiscal/enforcement pass: house 119/1 roll 168 (H.R. 4) carries % attributed member votes', n_house168;
  RAISE NOTICE 'Fiscal/enforcement pass: senate 119/1 roll 372 (H.R. 1) carries % attributed member votes', n_senate372;
  RAISE NOTICE 'Fiscal/enforcement pass: house 119/1 roll 190 (H.R. 1) carries % attributed member votes', n_house190;
  RAISE NOTICE 'Fiscal/enforcement pass: senate 119/1 roll 411 (H.R. 4) carries % attributed member votes', n_senate411;

  IF n_rolls <> 8 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: expected 8 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 414 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: expected at least 414 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: % member vote(s) on the rolls this pass created carry a politician_id outside db/vr-member-map.json', n_orphan;
  END IF;
  IF n_issues < 14 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: expected at least 14 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_pos < 1 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: expected at least 1 sponsorship row(s), found %', n_pos;
  END IF;
  IF n_afp <> 1 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: the america_first_fp mapping on the 119th H.R. 4 did not land (found % row(s))', n_afp;
  END IF;
  IF n_hr1_axes < 14 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: the 119th H.R. 1 should carry at least 14 mapped axes, found %', n_hr1_axes;
  END IF;
  -- Seven live axes from 20260719150000 and 20260721140000, plus america_first_fp.
  IF n_hr4_axes < 8 THEN
    RAISE EXCEPTION 'Fiscal/enforcement pass: the 119th H.R. 4 should carry at least 8 mapped axes, found %', n_hr4_axes;
  END IF;
  IF n_senate127 < 38 THEN
    RAISE EXCEPTION 'senate 119/1 roll 127 (S. 331) was not topped up — only % member votes, expected at least 38', n_senate127;
  END IF;
  IF n_house168 < 60 THEN
    RAISE EXCEPTION 'house 119/1 roll 168 (H.R. 4) was not topped up — only % member votes, expected at least 60', n_house168;
  END IF;
  IF n_senate372 < 38 THEN
    RAISE EXCEPTION 'senate 119/1 roll 372 (H.R. 1) was not topped up — only % member votes, expected at least 38', n_senate372;
  END IF;
  IF n_house190 < 60 THEN
    RAISE EXCEPTION 'house 119/1 roll 190 (H.R. 1) was not topped up — only % member votes, expected at least 60', n_house190;
  END IF;
  IF n_senate411 < 38 THEN
    RAISE EXCEPTION 'senate 119/1 roll 411 (H.R. 4) was not topped up — only % member votes, expected at least 38', n_senate411;
  END IF;
END $$;
